#!/usr/bin/env python3
import os
import pwd
import subprocess
import re
def get_current_user():
    return pwd.getpwuid(os.getuid()).pw_name
def switch_to_ruby_user():
    current_user = get_current_user()
    if current_user == "Ruby":
        return True
    if current_user == "root":
        try:
            ruby_uid = pwd.getpwnam("Ruby").pw_uid
            os.setuid(ruby_uid)
            return True
        except KeyError:
            return False
        except PermissionError:
            return False
    else:
        return False
def check_ssl_close_config():
    try:
        cmd = "ps ux | grep om_agent | grep -v grep | awk '{print $12}' | sed 's/\/[^\/]*$//' | uniq | xargs -I {} grep ssl_close {}/om_agent.conf 2>/dev/null"
        result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
        if result.returncode == 0 and result.stdout.strip():
            if "ssl_close = off" in result.stdout:
                return True
        return False
    except Exception as e:
        return False
def check_bashrc_source():
    bashrc_path = "/home/Ruby/.bashrc"
    current_user = get_current_user()
    if not os.path.exists(bashrc_path):
        return False
    try:
        with open(bashrc_path, 'r') as f:
            content = f.read()
            lines = content.split('\n')
            found = False
            for i, line in enumerate(lines, 1):
                line_stripped = line.strip()
                if not line_stripped or line_stripped.startswith('#'):
                    continue
                patterns = [
                    r'^\s*source\s+.*gauss_env_file',
                    r'^\s*\.\s+.*gauss_env_file',
                    r'^\s*source\s+["\']?.*gauss_env_file["\']?',
                ]
                for pattern in patterns:
                    if re.search(pattern, line_stripped):
                        found = True
                        break
                if found:
                    break
            if found:
                return True
        return False
    except Exception as e:
        return False
def main():
    if not switch_to_ruby_user():
        print("true", end="")
        return
    if get_current_user() != "Ruby":
        print("true", end="")
        return
    if not check_ssl_close_config():
        print("true", end="")
        return
    if check_bashrc_source():
        print("false", end="")
    else:
        print("true", end="")
if __name__ == "__main__":
    main()
